func (s *Service) DeleteDevice(ctx context.Context, id int64) error {
	if id <= 0 {
		return s.reject("delete_device", devicefleet.ErrInvalidDevice)
	}
	return s.runWrite(ctx, "delete_device", func(ctx context.Context, stats *domain.OperationStats) error {
		_, queryStats, err := s.deps.Devices.Delete(ctx, id)
		stats.Add(queryStats)
		return err
	})
}

func (s *Service) DeleteExpiredUnregisteredTagScans(ctx context.Context, cutoff time.Time) (int64, error) {
	if cutoff.IsZero() {
		return 0, s.reject("delete_expired_unregistered_tag_scans", devicefleet.ErrInvalidUnregisteredTagScan)
	}
	var deleted int64
	err := s.runWrite(ctx, "delete_expired_unregistered_tag_scans", func(ctx context.Context, stats *domain.OperationStats) error {
		var queryStats domain.OperationStats
		var err error
		deleted, queryStats, err = s.deps.Scans.DeleteExpired(ctx, cutoff)
		stats.Add(queryStats)
		return err
	})
	return deleted, err
}

func (s *Service) DeleteUnregisteredTagScansAfterRetention(ctx context.Context) (int, int, error) {
	cutoff := s.deps.Now().Add(-unregisteredTagScanRetentionWindow - retentionClockMargin)
	deleted, err := s.DeleteExpiredUnregisteredTagScans(ctx, cutoff)
	return int(deleted), devicefleet.UnregisteredTagScanRetentionDays, err
}

