func (r *ResolveUnregisteredTagScan) Normalize(now time.Time) {
	if r.Note != nil {
		trimmed := strings.TrimSpace(*r.Note)
		if trimmed == "" {
			r.Note = nil
		} else {
			r.Note = &trimmed
		}
	}
	if r.ResolvedAt.IsZero() {
		r.ResolvedAt = now
	}
}
